'use strict';
const test=require('node:test'),assert=require('node:assert/strict');
const Plan=require('./plan-core.js'),Core=require('./readiness-core.js'),catalog=require('./data/collection-catalog.json'),registry=require('./data/readiness-methods.json');
function fixture(){
 const o={company:{legal:'Independent QA Company',country:'United States'},period:{start:'2025-01-01',end:'2025-12-31'},boundary:{approach:'Operational control',operations:'All owned operations'},locations:[{id:'qa-site',name:'QA Site',included:'Include'}],sources:[{answer:'Yes',names:'QA Oven',location:'qa-site'},...Array.from({length:4},()=>({answer:'No',notes:'QA proposed exclusion'}))],changes:Array.from({length:5},()=>({answer:'No'})),review:{complete:true,needed:true,role:'QA preparer'}};
 let p=Plan.createPlan(o,catalog);const i=p.items['scope1:stationary'];i.subtypeId='oven';i.locationIds=['qa-site'];i.status='complete';i.records=[{id:'qa1',recordType:'Fuel bill',quantity:'12.00',unit:'therm',quality:'actual',periodStart:'2025-01-01',periodEnd:'2025-12-31',reference:'QA invoice'}];
 const m=registry.methods.find(m=>m.catalogId==='oven');i.readinessDetails=Object.fromEntries(m.requiredFields.map(f=>[f.id,'QA documented answer']));
 p=Plan.reconcile(o,p,catalog);p.items['scope1:stationary'].needsReview=false;return {o,p};
}
const evaluate=f=>Core.evaluate(f.o,f.p,catalog,registry);
const item=f=>evaluate(f).items.find(i=>i.id==='scope1:stationary');
test('actual registry maps selected oven with prepared details',()=>{const f=fixture(),i=item(f);assert.equal(i.methodId,'candidate-oven');assert.equal(i.status,'candidate-for-method-review');assert.equal(i.readyForCalculation,false);assert.equal(evaluate(f).readyForCalculation,false);});
test('unknown custom never inherits common method silently',()=>{const f=fixture();f.p.custom.push({id:'qa-custom',title:'Unknown QA process',scope:'unknown',familyId:'',locationIds:[],records:[]});const i=evaluate(f).items.find(i=>i.id.includes('qa-custom'));assert.equal(i.status,'unsupported');assert.equal(i.readyForCalculation,false);});
test('candidate units and actual catalog details control prepared inputs',()=>{const f=fixture(),saved=f.p.items['scope1:stationary'];saved.records[0].unit='kWh';saved.readinessDetails={approved:'yes',factorRelease:'released'};saved.readyForCalculation=true;const i=item(f);assert.equal(i.status,'needs-input');assert(i.findings.some(x=>x.code==='unit-incompatible'));assert(i.findings.some(x=>x.code==='detail-missing'));assert.equal(i.readyForCalculation,false);});
test('method details preserved across collection reconciliation and context change',()=>{const f=fixture(),details=f.p.items['scope1:stationary'].readinessDetails;assert.deepEqual(Plan.reconcile(f.o,f.p,catalog).items['scope1:stationary'].readinessDetails,details);f.o.locations[0].name='Corrected QA Site';const p=Plan.reconcile(f.o,f.p,catalog);assert.deepEqual(p.items['scope1:stationary'].readinessDetails,details);assert(p.items['scope1:stationary'].needsReview);});
test('overlap and duplicate retained despite arbitrary different record ids',()=>{const f=fixture(),i=f.p.items['scope1:stationary'];i.records.push({...i.records[0],id:'qa2'});const codes=item(f).findings.map(x=>x.code);assert(codes.includes('period-overlap'));assert(codes.includes('duplicate-record'));});
test('all No produces reviewed exclusions, never readiness or emissions',()=>{const f=fixture();f.o.sources.forEach(s=>{s.answer='No';s.notes='Proposed only';});Object.values(f.p.screening).forEach(s=>{s.answer='No';s.reason='Proposed only';});const r=evaluate(f);assert.equal(r.readyForCalculation,false);assert(r.items.every(i=>i.status==='excluded-pending-review'));assert(!Object.hasOwn(r,'emissions'));});
test('actual scope3 empty unit policy remains blocked after every detail is populated',()=>{const f=fixture();f.p.screening['category-1']={answer:'Yes',locationMode:'company-wide'};f.p=Plan.reconcile(f.o,f.p,catalog);const i=f.p.items['scope3:category-1'],m=registry.methods.find(m=>m.catalogId==='category-1');i.records=[{id:'cat1',recordType:'QA purchases',quantity:'99',unit:'arbitrary widget',quality:'actual',periodStart:'2025-01-01',periodEnd:'2025-12-31',reference:'QA ledger'}];i.readinessDetails=Object.fromEntries(m.requiredFields.map(x=>[x.id,'QA answer']));i.needsReview=false;const result=evaluate(f).items.find(i=>i.id==='scope3:category-1');assert.equal(result.status,'needs-input');assert(result.findings.some(x=>x.code==='unit-policy-unresolved'));assert.equal(result.readyForCalculation,false);});
